@Injectable()
export class FileService {
  constructor(private readonly fileStorage: FileStorageService) {}

  async storeFavicon({
    domainName,
    file,
    size,
  }: {
    file: Buffer;
    domainName: string;
    size: string;
  }) {
    await this.fileStorage.write({
      file,
      name: `${size}.png`,
      mimeType: 'image/png',
      folder: `favicon/${domainName}`,
