  fetchFavicon({
    domainName,
    size,
  }: {
    domainName: string;
    size: string;
  }): Promise<Readable> {
    return this.fileStorage.read({
      folderPath: `favicon/${domainName}`,
      filename: `${size}.png`,
    });
  }

  async listFiles(chunkSize: number, olderThan: Date) {
    return this.fileStorage.listFiles(chunkSize, olderThan);
  }
}

import sharp from 'sharp';

import { Favicon } from '../interfaces/favicon.interface';

export class ImageManipulation {
  static getLargestFaviconFile(
    faviconFiles: Array<Favicon>,
    size: number,
  ): Favicon {
    const largestFaviconFile = faviconFiles.reduce((prev, current) => {
      return current.width > prev.width ? current : prev;
    });

    if (
      largestFaviconFile.format !== 'svg' &&
      largestFaviconFile.width < size
    ) {
      return null;
    }
    return largestFaviconFile;
  }

  static getSmallestFaviconLargerThanSize(
    faviconFiles: Array<Favicon>,
    size: number,
  ): Favicon | null {
    const smallest = faviconFiles.reduce((smallest, current) => {
      // If the current favicon is larger than the desired size and either we
      // don't have a smallest favicon yet or the current one is smaller than
      // the smallest one we've found so far
      return current.width >= size &&
        (!smallest || current.width < smallest.width)
        ? current
        : smallest;
    }, null);

    return (
      smallest ?? ImageManipulation.getLargestFaviconFile(faviconFiles, size)
    );
  }

  static async convertFaviconFileToPngAndResize(
    faviconFile: Favicon,
    size: number,
  ): Promise<Favicon> {
    const convertedFile = await sharp(faviconFile.file)
      .resize(size)
      .png()
      .toBuffer();
    const convertedFileMetadata = await sharp(convertedFile).metadata();

    return {
      width: convertedFileMetadata.width,
      height: convertedFileMetadata.height,
      file: convertedFile,
      url: null,
      format: convertedFileMetadata.format,
    };
  }

  static isIcoFile(buffer: Buffer): boolean {
    const icoSignature = Uint8Array.from([0, 0, 1, 0]); // The first four bytes of ICO format
    return buffer.subarray(0, 4).equals(icoSignature);
  }

  static isSVGFile(buffer: Buffer): boolean {
    const svgTag = '<svg';
    const bufferAsString = buffer.toString(
      'utf-8',
      0,
      Math.min(buffer.length, 100),
    );
    return bufferAsString.includes(svgTag);
  }

  static isPNGFile(buffer: Buffer): boolean {
    const pngSignature = Uint8Array.from([
      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    ]);
    return buffer.subarray(0, 8).equals(pngSignature);
  }

  static isAlmostSquare(favicon: Favicon): boolean {
    if (favicon.height === 0 || favicon.width === 0) {
      return false;
    }
    return (
      favicon.width / favicon.height > 0.9 &&
      favicon.width / favicon.height < 1.1
    );
  }
}

import { Command, CommandRunner, Option } from 'nest-commander';
import { FaviconService } from 'src/favicon/favicon.service';
import { FileService } from 'src/favicon/file.service';
import { Domain } from 'src/favicon/utils/domain';

interface BasicCommandOptions {
  refresh?: string;
  size?: number;
  refetch?: boolean;
}

@Command({ name: 'domain', description: 'A domain util' })
export class DomainCommandService extends CommandRunner {
  constructor(
    private readonly faviconService: FaviconService,
    private readonly fileService: FileService,
  ) {
    super();
  }

  async run(
    passedParam: string[],
    options?: BasicCommandOptions,
  ): Promise<void> {
    if (options.refresh) {
      this.refreshDomain(options.refresh, options.size, passedParam);
    } else if (options.refetch) {
      this.refetchOldestDomains();
    }
  }

  @Option({
    flags: '-r, --refresh [domain]',
    description: 'Refresh a domain',
  })
  parseDomain(val: string): string {
    return val;
  }

  @Option({
    flags: '-s, --size [size]',
    description: 'Refresh a domain',
  })
  parseSize(val: string): number {
    return Number(val);
  }

  @Option({
    flags: '-f, --refetch [refetch]',
    description: 'Refetch oldest domain',
  })
  parseRefetch(val: string): boolean {
    return Boolean(val);
  }

  async refreshDomain(
    domainName: string,
    _size?: number,
    _param?: string[],
  ): Promise<void> {
    try {
      if (!Domain.checkDomainIsValid(domainName)) {
        throw new Error('Invalid domain name provided');
      }

      await this.faviconService.storeFavicon(domainName);
    } catch (error) {
      console.error(error);
      process.exit(1);
    }
  }

  async refetchOldestDomains() {
    const today = new Date();

    const oneWeekAgo = new Date(today);
    oneWeekAgo.setDate(today.getDate() - 7);

    const domains = (await this.fileService.listFiles(1000, oneWeekAgo)).slice(
      0,
      20,
    );

    await Promise.all(domains.map((domain) => this.refreshDomain(domain)));
  }
}

